    else if (ih2 == 2) c2 = colour[2];
    else if (ih2 == 3) c2 = colour[3];
    
    vec3 rgbA = hsv2rgb(vec3(c1, CYCLE_SATURATION/255.0, CYCLE_VALUE/255.0));
