        float pd   = length(vec2(pdx, pdy));
        float wave = sin(atan(pdy, pdx) * 5.0 + u_time * 3.0) * u_vendor_radius * 0.15;
        sh = min(sh, smoothstep(0.0, u_vendor_radius + wave, pd));
